package edu.pe.cibertec.saibm.usuario.infrastructure.persistence; import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import edu.pe.cibertec.saibm.usuario.domain.model.*; @Entity @Table(name="user_profiles") public class UserJpaEntity {@Id UUID id;@Column(name="first_name",nullable=false)String firstName;@Column(name="last_name",nullable=false)String lastName;@Column(nullable=false)String dni;@Column(nullable=false,unique=true)String email;@Enumerated(EnumType.STRING)@Column(nullable=false)AccountStatus status;@Column(name="created_at",nullable=false)Instant createdAt;@Column(name="updated_at",nullable=false)Instant updatedAt;@Column(name="legacy_user_id",unique=true)String legacyUserId;protected UserJpaEntity(){}public UserJpaEntity(UserProfile p){id=p.id();firstName=p.firstName();lastName=p.lastName();dni=p.dni();email=p.email();status=p.status();createdAt=p.createdAt();updatedAt=p.updatedAt();legacyUserId=p.legacyUserId();}public UserProfile domain(){return new UserProfile(id,firstName,lastName,dni,email,status,createdAt,updatedAt,legacyUserId);}}
